def main():
    import sys
    sys.path.insert(0, str(Path(__file__).resolve().parent))
    from i18n_pages import PAGES, TEMPLATES  # telas Registrar, Radiação, Análise, Registros, Método e perguntas do TRI-22
    rows = T + PAGES
    seen, problems = set(), []
    for pt, en, es in rows + TEMPLATES:
        if pt in seen:
            problems.append(f"chave repetida: {pt!r}")
        seen.add(pt)
        ph = sorted(re.findall(r"\{\w+\}", pt))
        for lang, txt in (("en", en), ("es", es)):
            if sorted(re.findall(r"\{\w+\}", txt)) != ph:
                problems.append(f"placeholders diferentes em {lang}: {pt!r}")
            if "\u2014" in txt:
                problems.append(f"travessão em {lang}: {pt!r}")
    if problems:
        raise SystemExit("\n".join(problems))
    for i, lang in ((1, "en"), (2, "es")):
        d = {row[0]: row[i] for row in rows}
        body = json.dumps(d, ensure_ascii=False, indent=0)
        tpl = json.dumps([[row[0], row[i]] for row in TEMPLATES], ensure_ascii=False, indent=0)
        (SRC / f"i18n-{lang}.js").write_text(
            f"/* Gerado por web/i18n_build.py. Não edite à mão. */\nwindow.I18N.add('{lang}', {body});\nwindow.I18N.addTemplates('{lang}', {tpl});\n",
            encoding="utf-8")
    print(f"{len(rows)} frases e {len(TEMPLATES)} modelos em en e es")


if __name__ == "__main__":
    main()
